"use client";

import { useEffect, useRef, useState } from "react";
import { allPages, api, type Snapshot } from "@/lib/api";
import type { components } from "@/lib/api-schema";

type Analysis = components["schemas"]["AnalysisOut"];
type ModelStatus = components["schemas"]["ModelStatusOut"];
import { human } from "./evidence-views";
import { AnswerBody } from "./answer-view";
import { AbstractionView } from "./abstraction-view";
import { DocumentTimeline } from "./document-timeline";
import { ReadableAbstractionView } from "./readable-abstraction-view";
import { CourseOfCareView } from "./course-of-care-view";

type View = "abstraction" | "ask" | "documents";

export function ClinicalPanel({
  patientId,
  csrf,
  snapshot,
  snapshots,
  onSnapshot,
  view,
  onSource,
}: {
  patientId: string;
  csrf: string;
  snapshot: Snapshot | undefined;
  snapshots: Snapshot[];
  onSnapshot: (id: string) => void;
  view: View;
  onSource: (revision: string, span: string) => void;
}) {
  const [runs, setRuns] = useState<Analysis[]>([]);
  const [model, setModel] = useState<ModelStatus | null>(null);
  const [selected, setSelected] = useState("");
  const [question, setQuestion] = useState("");
  const [error, setError] = useState("");
  const [sending, setSending] = useState(false);
  const [loading, setLoading] = useState(true);
  const retry = useRef<{ signature: string; key: string } | null>(null);

  const loadedVersion = useRef("");
  useEffect(() => {
    let disposed = false;
    let timer: ReturnType<typeof setTimeout>;
    loadedVersion.current = "";
    const poll = async () => {
      try {
        // Poll a small change marker; download full results only when something changed.
        const { version } = await api<{ version: string }>(
          `/patients/${patientId}/analyses/version`,
        );
        if (version !== loadedVersion.current) {
          const [values, status] = await Promise.all([
            allPages<Analysis>(`/patients/${patientId}/analyses`),
            api<ModelStatus>("/model-status"),
          ]);
          if (!disposed) {
            loadedVersion.current = version;
            setRuns(
              values.sort((a, b) => b.created_at.localeCompare(a.created_at)),
            );
            setModel(status);
          }
        }
        if (!disposed) setLoading(false);
      } catch (e) {
        if (!disposed) {
          setError(e instanceof Error ? e.message : "Unable to load analysis");
          setLoading(false);
        }
      }
      if (!disposed) timer = setTimeout(poll, 2500);
    };
    void poll();
    return () => {
      disposed = true;
      clearTimeout(timer);
    };
  }, [patientId]);

  const matching = runs.filter((run) => run.snapshot_id === snapshot?.id);
  const documentRuns = matching.filter(
    (run) => !!run.result?.document_catalog && run.status === "succeeded",
  );
  const documentRun =
    documentRuns.find((run) => run.id === selected) ?? documentRuns[0];
  const displayedRuns =
    view === "documents"
      ? documentRuns
      : matching.filter(
          (run) => run.kind === "abstraction" && run.status === "succeeded",
        );
  const abstractions = matching.filter(
    (run) => run.kind === "abstraction" && run.status === "succeeded",
  );
  const abstraction =
    abstractions.find((run) => run.id === selected) ?? abstractions[0];
  const draft = abstraction?.result?.abstraction;
  const readable = abstraction?.result?.readable_abstraction;
  const checkedSources = new Set(
    readable?.reviews
      ?.filter((review) => review.status === "checked")
      .map((review) => review.target_ref),
  );
  const canAsk =
    readable?.documents.some((document) =>
      checkedSources.has(document.profile.revision_id),
    ) ?? false;
  const active = runs.find((run) => ["queued", "running"].includes(run.status));
  const answers = matching.filter(
    (run) => run.kind === "answer" && run.abstraction_id === abstraction?.id,
  );

  async function submit(kind: "abstraction" | "answer" | "documents") {
    if (!snapshot || (kind === "answer" && (!question.trim() || !abstraction)))
      return;
    setSending(true);
    setError("");
    const payload = {
      snapshot_id: snapshot.id,
      ...(kind === "documents" ? { document_catalog: true } : {}),
      ...(kind === "answer"
        ? { abstraction_id: abstraction!.id, question: question.trim() }
        : {}),
    };
    const signature = JSON.stringify(payload);
    if (retry.current?.signature !== signature)
      retry.current = { signature, key: crypto.randomUUID() };
    try {
      const run = await api<Analysis>(`/patients/${patientId}/analyses`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-CSRF-Token": csrf,
          "Idempotency-Key": retry.current.key,
        },
        body: signature,
      });
      setRuns((current) => [
        run,
        ...current.filter((value) => value.id !== run.id),
      ]);
      retry.current = null;
      if (kind === "answer") setQuestion("");
      else setSelected("");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Unable to start analysis");
    } finally {
      setSending(false);
    }
  }

  return (
    <section className="panel clinical-panel">
      <div className="clinical-heading">
        <div>
          <span className="eyebrow">CLAUDE · SOURCE-LINKED DRAFT</span>
          <h2>
            {view === "documents"
              ? "Document timeline"
              : view === "abstraction"
                ? "Clinical abstraction"
                : "Ask the record"}
          </h2>
          <p>
            {view === "documents"
              ? "Inspect what each record is, who contributed or signed it, and its history."
              : view === "abstraction"
                ? "Inspect encounters, conflicting accounts, and the clinical course."
                : "Ask a question about this patient's selected source snapshot."}
          </p>
        </div>
        {view !== "abstraction" && (
          <label className="snapshot-picker">
            Source snapshot
            <select
              aria-label="Analysis source snapshot"
              value={snapshot?.id ?? ""}
              onChange={(event) => {
                onSnapshot(event.target.value);
                setSelected("");
              }}
            >
              {snapshots.map((value) => (
                <option key={value.id} value={value.id}>
                  v{value.sequence} · {value.manifest.length} sources
                </option>
              ))}
            </select>
          </label>
        )}
      </div>
      {error && (
        <div className="alert error" role="alert">
          {error}
        </div>
      )}
      {view !== "abstraction" &&
        snapshot &&
        snapshot.id !== snapshots[0]?.id && (
          <div className="alert warning">
            Historical snapshot. Newer imports are not included.
          </div>
        )}
      {model && !model.configured && (
        <div className="alert warning">
          Claude is not configured. Add EHR_ANTHROPIC_API_KEY to the server’s
          .env file and restart the services.
        </div>
      )}
      {view !== "ask" && (
        <div className="analysis-actions">
          <span>{model?.model ?? "Checking Claude configuration…"}</span>
          <button
            className="primary"
            disabled={
              loading || !model?.configured || !snapshot || !!active || sending
            }
            onClick={() =>
              void submit(view === "documents" ? "documents" : "abstraction")
            }
          >
            {sending
              ? "Starting…"
              : view === "documents"
                ? documentRun
                  ? "Refresh document timeline"
                  : "Generate document timeline"
                : draft
                  ? "Run new abstraction"
                  : "Generate abstraction"}
          </button>
        </div>
      )}
      {active && (
        <div className="alert" role="status">
          {active.kind === "documents"
            ? "Extracting document metadata with Claude"
            : active.kind === "abstraction"
              ? "Extracting, checking and reconciling sources with Claude"
              : "Preparing a cited answer"}{" "}
          · {active.status}. You can leave this page and return later.
          {active.progress && (
            <p>
              {active.progress.validated_documents} of{" "}
              {active.progress.total_documents} documents processed
              {active.progress.failed_documents > 0 &&
                ` · ${active.progress.failed_documents} need attention`}
              {active.progress.validated_documents +
                active.progress.failed_documents ===
                active.progress.total_documents &&
                active.kind === "abstraction" &&
                " · Preparing reconciliation proposals"}
            </p>
          )}
        </div>
      )}
      {matching
        .filter(
          (run) =>
            run.kind === (view === "documents" ? "documents" : "abstraction"),
        )
        .slice(0, 1)
        .filter((run) => run.status === "failed")
        .map((run) => (
          <div className="alert warning" key={run.id}>
            {view === "documents" ? "Document metadata" : "Abstraction"} failed:{" "}
            {human(run.error_code ?? "processing failed")}. Correct the issue,
            then start a new run.
          </div>
        ))}
      {displayedRuns.length > 1 && (
        <label className="run-picker">
          {view === "documents"
            ? "Document metadata version"
            : "Abstraction version"}
          <select
            aria-label={
              view === "documents"
                ? "Document metadata version"
                : "Abstraction version"
            }
            value={(view === "documents" ? documentRun : abstraction)?.id ?? ""}
            onChange={(event) => setSelected(event.target.value)}
          >
            {displayedRuns.map((run) => (
              <option key={run.id} value={run.id}>
                {new Date(run.created_at).toLocaleString()}
              </option>
            ))}
          </select>
        </label>
      )}
      {view === "documents" ? (
        documentRun ? (
          <>
            <DocumentTimeline
              key={documentRun.id}
              run={documentRun}
              patientId={patientId}
              onSource={onSource}
            />
            <div className="analysis-provenance">
              {documentRun.model} · {documentRun.prompt_version} ·{" "}
              {new Date(documentRun.created_at).toLocaleString()}
            </div>
          </>
        ) : (
          <div className="empty">
            <h3>
              {loading
                ? "Loading document history…"
                : "Document metadata has not been extracted"}
            </h3>
            <p>
              Generate the timeline from this snapshot. This sends the selected
              fictional records to Anthropic and preserves your existing
              clinical abstraction.
            </p>
          </div>
        )
      ) : !draft ? (
        <div className="empty">
          <h3>
            {loading
              ? "Loading analysis…"
              : "Sources are ready for abstraction"}
          </h3>
          <p>
            Generate an abstraction to review the evidence and ask questions.
            This sends the selected fictional records to Anthropic.
          </p>
        </div>
      ) : (
        <>
          <div className="draft-notice">
            Unreviewed AI draft ·{" "}
            {draft.coverage.filter((item) => item.status === "reviewed").length}
            /{snapshot?.manifest.length} sources represented · Source links are
            verified; clinical interpretations still need review.
          </div>
          {!abstraction.result?.readable_abstraction && (
            <p className="alert warning">
              This is an older abstraction format. Run a new abstraction to use
              the readable view and updated querying.
            </p>
          )}
          {view === "abstraction" ? (
            abstraction.result?.readable_abstraction ? (
              <>
                <CourseOfCareView
                  key={`${abstraction.id}-course`}
                  patientId={patientId}
                  runId={abstraction.id}
                  onSource={onSource}
                />
                <details className="encounter-ledger">
                  <summary>Per-document abstractions</summary>
                  <ReadableAbstractionView
                    key={abstraction.id}
                    run={abstraction}
                    onSource={onSource}
                  />
                </details>
                {draft.encounters.length > 0 && (
                  <details className="encounter-ledger">
                    <summary>
                      Encounter ledger and calculated totals (
                      {draft.encounters.length} encounters)
                    </summary>
                    <AbstractionView
                      key={`${abstraction.id}-ledger`}
                      run={abstraction}
                      onSource={onSource}
                    />
                  </details>
                )}
              </>
            ) : (
              <AbstractionView
                key={abstraction.id}
                run={abstraction}
                onSource={onSource}
              />
            )
          ) : (
            <>
              <form
                className="question-form"
                onSubmit={(event) => {
                  event.preventDefault();
                  void submit("answer");
                }}
              >
                <label htmlFor="clinical-question">Your question</label>
                {!canAsk && (
                  <p className="muted-text">
                    Source checks are still needed before querying. Re-run the
                    abstraction to retry flagged sources.
                  </p>
                )}
                <textarea
                  id="clinical-question"
                  rows={3}
                  maxLength={2000}
                  placeholder="What changed over the review period? Which treatment time is uncertain?"
                  value={question}
                  onChange={(event) => setQuestion(event.target.value)}
                />
                <div className="question-examples">
                  {[
                    "How many psychotherapy sessions, days, and minutes are documented?",
                    "Were the documented weekly treatment goals met?",
                    "Summarize changes in symptoms and functioning.",
                  ].map((value) => (
                    <button
                      type="button"
                      key={value}
                      onClick={() => setQuestion(value)}
                    >
                      {value}
                    </button>
                  ))}
                </div>
                <button
                  className="primary"
                  disabled={
                    !question.trim() ||
                    !canAsk ||
                    !!active ||
                    sending ||
                    !model?.configured
                  }
                >
                  Ask
                </button>
              </form>
              <div className="answer-history">
                {answers.map((run) => (
                  <article className="answer-card" key={run.id}>
                    <span className="eyebrow">
                      {new Date(run.created_at).toLocaleString()} ·{" "}
                      {run.result?.answer?.status ?? run.status}
                    </span>
                    <h3>{run.question}</h3>
                    {run.error_code && (
                      <p className="alert warning">{human(run.error_code)}</p>
                    )}
                    {run.result?.answer && (
                      <AnswerBody result={run.result} onSource={onSource} />
                    )}
                    {["queued", "running"].includes(run.status) && (
                      <p role="status">Preparing answer…</p>
                    )}
                  </article>
                ))}
              </div>
            </>
          )}
          <div className="analysis-provenance">
            {abstraction.model} · {abstraction.prompt_version} ·{" "}
            {new Date(abstraction.created_at).toLocaleString()} ·{" "}
            {abstraction.usage?.input_tokens.toLocaleString()} input /{" "}
            {abstraction.usage?.output_tokens.toLocaleString()} output tokens
          </div>
        </>
      )}
    </section>
  );
}
